const enqueueDispatch = `-- name: EnqueueDispatch :exec
INSERT INTO dispatch_outbox (
  target_user_id,
  pts,
  event_type,
  exclude_auth_key_id,
  exclude_session_id
)
VALUES (
  $1,
  $2,
  $3,
  $4,
  $5
)
ON CONFLICT DO NOTHING
`

type EnqueueDispatchParams struct {
	TargetUserID     int64
	Pts              int32
	EventType        string
	ExcludeAuthKeyID []byte
	ExcludeSessionID int64
}

func (q *Queries) EnqueueDispatch(ctx context.Context, arg EnqueueDispatchParams) error {
	_, err := q.db.Exec(ctx, enqueueDispatch,
		arg.TargetUserID,
		arg.Pts,
		arg.EventType,
		arg.ExcludeAuthKeyID,
		arg.ExcludeSessionID,
	)
	return err
}

const getUserUpdateWatermark = `-- name: GetUserUpdateWatermark :one
SELECT contiguous_pts
FROM user_update_watermarks
WHERE user_id = $1
`

func (q *Queries) GetUserUpdateWatermark(ctx context.Context, userID int64) (int32, error) {
	row := q.db.QueryRow(ctx, getUserUpdateWatermark, userID)
	var contiguous_pts int32
	err := row.Scan(&contiguous_pts)
	return contiguous_pts, err
}

